"""Recover exact UI CSS and JS from the resource chunks generated by build_native."""
from __future__ import annotations
import base64, gzip, json, re
from pathlib import Path

def unpack(root: Path) -> tuple[str, str]:
    site = root / 'build' / 'served-native-ui'
    meta=json.loads((root/'build'/'VALIDATION.json').read_text())
    files=[site / name.lstrip('/') for name in meta['repurposed_original_help_pages']]
    full='\n'.join(f.read_text('ascii') for f in files)
    codes=''.join(re.findall(r'window\.H910P_PACK\+="([A-Za-z0-9+/=]+)";',full))
    if not codes: raise ValueError('No packed assets in native ROM resources')
    css,js=gzip.decompress(base64.b64decode(codes)).decode('utf-8').split('\0',1)
    if '</script' in js.lower(): raise ValueError('Embedded JS closes script element')
    if '</style' in css.lower(): raise ValueError('Embedded CSS closes style element')
    return css,js

def inline_html(root: Path) -> str:
    css,js=unpack(root)
    return '<!doctype html><html><head><style>'+css+'</style></head><body><main id="app"></main><script>'+js+'</script></body></html>'
